import re


class NotFound(Exception):
    pass


CAPTURE = re.compile(r"<(?:(int|str):)?(\w+)>")
REGEX = {"int": "[0-9]+", "str": "[^/]+", None: "[^/]+"}


def compile_route(route):
    pattern = ""
    converters = {}
    position = 0
    for match in CAPTURE.finditer(route):
        kind, name = match.groups()
        pattern += re.escape(route[position:match.start()])
        pattern += f"(?P<{name}>{REGEX[kind]})"
        converters[name] = kind
        position = match.end()
    pattern += re.escape(route[position:])
    return re.compile(pattern), converters


def resolve(url, patterns):
    for route, view in patterns:
        regex, converters = compile_route(route)
        match = regex.fullmatch(url)
        if match:
            kwargs = match.groupdict()
            for name, kind in converters.items():
                if kind == "int":
                    kwargs[name] = int(kwargs[name])
            return view, kwargs
    raise NotFound(url)

